-- Schema the pre-migration API built with EF Core 8 EnsureCreated (Database.GenerateCreateScript, postgres provider),
-- captured on 8 Oct 2026 from the net8.0 build before C9a.0. The live Railway Postgres has this schema. Do not edit.
CREATE TABLE "Lobbies" (
    "Id" uuid NOT NULL,
    "Code" character varying(6) NOT NULL,
    "IsPublic" boolean NOT NULL,
    "Status" character varying(16) NOT NULL,
    "HostPlayerId" uuid NOT NULL,
    "HostStatus" character varying(16) NOT NULL,
    "HostDraftJson" text,
    "GuestPlayerId" uuid,
    "GuestStatus" character varying(16),
    "GuestDraftJson" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    "LastActivityAt" timestamp with time zone NOT NULL,
    "MatchId" uuid,
    "Seed" bigint,
    "MatchServer" text,
    CONSTRAINT "PK_Lobbies" PRIMARY KEY ("Id")
);


CREATE TABLE "Matches" (
    "Id" uuid NOT NULL,
    "LobbyId" uuid NOT NULL,
    "HostPlayerId" uuid NOT NULL,
    "GuestPlayerId" uuid NOT NULL,
    "Seed" bigint NOT NULL,
    "Status" character varying(24) NOT NULL,
    "WinnerPlayerId" uuid,
    "DurationSeconds" integer,
    "FinalStatsJson" text,
    "DecidedBy" text,
    "CreatedAt" timestamp with time zone NOT NULL,
    "FirstReportAt" timestamp with time zone,
    "DecidedAt" timestamp with time zone,
    "HostRatingBefore" integer,
    "HostRatingAfter" integer,
    "GuestRatingBefore" integer,
    "GuestRatingAfter" integer,
    CONSTRAINT "PK_Matches" PRIMARY KEY ("Id")
);


CREATE TABLE "MatchReports" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MatchId" uuid NOT NULL,
    "PlayerId" uuid NOT NULL,
    "WinnerPlayerId" uuid NOT NULL,
    "DurationSeconds" integer NOT NULL,
    "StatsJson" text NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_MatchReports" PRIMARY KEY ("Id")
);


CREATE TABLE "Players" (
    "Id" uuid NOT NULL,
    "Name" character varying(16) NOT NULL,
    "TokenHash" character varying(64) NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "Rating" integer NOT NULL,
    "Wins" integer NOT NULL,
    "Losses" integer NOT NULL,
    CONSTRAINT "PK_Players" PRIMARY KEY ("Id")
);


CREATE TABLE "Runs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" uuid NOT NULL,
    "Kills" integer NOT NULL,
    "RunSeconds" integer NOT NULL,
    "Level" integer NOT NULL,
    "Captain" character varying(32),
    "MapId" character varying(32) NOT NULL,
    "BuildHash" character varying(128),
    "ClientVersion" character varying(32),
    "WeekStart" timestamp with time zone NOT NULL,
    "SubmittedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_Runs" PRIMARY KEY ("Id")
);


CREATE TABLE "WeeklyBests" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "PlayerId" uuid NOT NULL,
    "WeekStart" timestamp with time zone NOT NULL,
    "MapId" character varying(32) NOT NULL,
    "Kills" integer NOT NULL,
    "RunSeconds" integer NOT NULL,
    "Level" integer NOT NULL,
    "Captain" character varying(32),
    "RunId" bigint NOT NULL,
    "AchievedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "PK_WeeklyBests" PRIMARY KEY ("Id")
);


CREATE UNIQUE INDEX "IX_Lobbies_Code" ON "Lobbies" ("Code");


CREATE INDEX "IX_Lobbies_Status_IsPublic" ON "Lobbies" ("Status", "IsPublic");


CREATE INDEX "IX_Matches_Status" ON "Matches" ("Status");


CREATE UNIQUE INDEX "IX_MatchReports_MatchId_PlayerId" ON "MatchReports" ("MatchId", "PlayerId");


CREATE UNIQUE INDEX "IX_Players_TokenHash" ON "Players" ("TokenHash");


CREATE INDEX "IX_Runs_PlayerId" ON "Runs" ("PlayerId");


CREATE INDEX "IX_WeeklyBests_WeekStart_MapId_Kills" ON "WeeklyBests" ("WeekStart", "MapId", "Kills");


CREATE UNIQUE INDEX "IX_WeeklyBests_WeekStart_MapId_PlayerId" ON "WeeklyBests" ("WeekStart", "MapId", "PlayerId");


